# Turns the land joined to (row, col) into water, so it's counted once.
def sink(grid: list[list[str]], row: int, col: int) -> None:
    if row < 0 or row >= len(grid) or col < 0 or col >= len(grid[0]):
        return
    if grid[row][col] != "#":
        return
    grid[row][col] = "."
    sink(grid, row + 1, col)
    sink(grid, row - 1, col)
    sink(grid, row, col + 1)
    sink(grid, row, col - 1)


def num_islands(grid: list[list[str]]) -> int:
    count = 0
    for row in range(len(grid)):
        for col in range(len(grid[0])):
            if grid[row][col] == "#":
                count += 1
                sink(grid, row, col)
    return count


rows, cols = map(int, input().split())
grid = [list(input().strip()) for _ in range(rows)]
