import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

// Turns the land joined to (row, col) into water, so it's counted once.
// Off the grid, the lookups give undefined, which isn't land.
function sink(grid: string[][], row: number, col: number): void {
  const line = grid[row];
  if (line === undefined || line[col] !== "#") {
    return;
  }
  line[col] = ".";
  sink(grid, row + 1, col);
  sink(grid, row - 1, col);
  sink(grid, row, col + 1);
  sink(grid, row, col - 1);
}

function numIslands(grid: string[][]): number {
  let count = 0;
  for (const [row, line] of grid.entries()) {
    for (const [col, cell] of line.entries()) {
      if (cell === "#") {
        count++;
        sink(grid, row, col);
      }
    }
  }
  return count;
}

const lines = input.trim().split("\n");
const rows = Number(lines[0]?.split(" ")[0] ?? 0);
const grid = lines.slice(1, 1 + rows).map((line) => line.trim().split(""));
